  // Происшествия
  const BEAST = { german: ['гусь', 'аист'], italy: ['осёл', 'голубь'], latam: ['осёл', 'попугай'], asia: ['буйвол', 'слон'], africa: ['козёл', 'бабуин'], europe: ['гусь', 'медведь из цирка'], mideast: ['верблюд', 'кот'], steppe: ['баран', 'беркут'] };
