    if (S.economy >= 55) T.push('Финансовый успех близок! Экономика растёт, и вы — вместе с ней.');
    if (S.era === '2000') T.push('Не публикуйте ничего в интернете до четверга. И после четверга тоже.', 'Ваш телефон знает о вас больше, чем вы думаете. И не только телефон.');
    if (S.era === '1848') T.push('Звёзды благоприятствуют путешествиям. Почтовая карета, впрочем, против.', 'Юпитер советует не читать запрещённых брошюр. Особенно вслух.', 'Возможна дуэль. Выбирайте секундантов среди непьющих.', 'Удачный день для дагерротипа: сидите смирно и не думайте о политике.', 'Меркурий в доме цензора: письма дойдут, но немного прочитанными.');
