const MINISTER_EXTRA = {
  defense: [['Сколько у вас орденов?', 'Сорок семь. Сорок восьмой — за скромность — вручат в пятницу.'], ['Что подарить армии на праздник?', S => S.era === '1848' ? 'Пушку. Можно трофейную. Лучше две.' : 'Танк. Можно подержанный. Лучше два.']],
  economy: [['Когда вырастут зарплаты?', 'Сразу после цен. Мы движемся по очереди.'], ['Где вы храните сбережения?', 'В национальной валюте! Часть. Небольшую. Остальное — в надёжных местах.']],
  police: [['Сколько у вас сотрудников?', 'Достаточно, чтобы один из них сейчас читал этот ответ вместе с вами.'], ['Есть ли в стране оппозиция?', S => S.fear >= 55 ? 'Была. Теперь отдыхает.' : 'Есть. Мы её очень внимательно слушаем. Круглосуточно.']],
  propaganda: [['Какой ваш любимый жанр?', 'Оптимистическая трагедия. С хорошим концом для правительства.'], ['Будет ли в стране свободная пресса?', 'Конечно. Свободная от ошибок, лжи и вредных мыслей.']],
  foreign: [['Какой язык самый важный для дипломата?', 'Язык жестов. Особенно жест «давайте обсудим за ужином».'], ['Боитесь ли вы войны?', S => S.army >= 60 ? 'Пусть нас боятся. Мы мирные, но вооружённые.' : (S.era === '1848' ? 'Мы со всеми дружим. Особенно с теми, у кого пушек больше.' : 'Мы со всеми дружим. Особенно с теми, у кого танков больше.')]],
};
const _ivOrig = UI.interview;
UI.interview = function () {
  const base = _ivOrig.call(UI);
  const roles = Object.keys(ROLES), key = roles[S.turn % roles.length];
  const ex = (MINISTER_EXTRA[key] || []).map(([q, a]) => [q, typeof a === 'function' ? a(S) : a]);
  const r = PressGen.rng(5), all = [...base.qa, ...ex];
  for (let i = all.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [all[i], all[j]] = [all[j], all[i]]; }
  return { ...base, qa: all.slice(0, 3), name: base.A.name, look: base.A.look, kind: '' };
};

